INSERT INTO flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note)
VALUES ('gdelt_aerospatial', 'actualite', 'aerospatial', 'GDELT — actualité aérospatiale (commandes, cadences, lancements)', 'https://api.gdeltproject.org/api/v2/doc/doc', E'{"_note": "Requête simplifiée le 23.08.2026, même motif que gdelt_medical. Répond 200 avec 49 articles, vérifié en réponse réelle le 23.08.2026. Bruit visible dans les intitulés (aviation de loisir, analyse boursière) : c''est au triage de le trancher, et le taux constaté sera une mesure.", "limite": 50, "fenetre": "7d", "requete": "(\\"aircraft orders\\" OR \\"aerospace supplier\\" OR \\"aircraft production\\")", "requete_statut": "simplifiee_23.08.2026", "requete_anterieure": "(aerospace (orders OR \\"production rate\\" OR supplier) OR \\"aircraft orders\\")"}'::jsonb, 'actif', 'N. Castillo', '2026-08-24'::date, 'GDELT DOC 2.0, requête SIMPLIFIÉE, même réserve que gdelt_medical. Vue en réponse réelle le 23.08.2026, 49 articles, dont plusieurs manifestement hors sujet (aéroports, titres boursiers) — la charge de tri retombe sur le triage IA et l''examen humain.')
ON CONFLICT (flux_id) DO NOTHING;
INSERT INTO flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note)
