INSERT INTO flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note)
VALUES ('gdelt_medical', 'actualite', 'medical', 'GDELT — actualité medtech (réglementation, investissements)', 'https://api.gdeltproject.org/api/v2/doc/doc', E'{"_note": "Requête simplifiée le 23.08.2026 (décision d''étudiant, notes de rédaction). L''ancienne, à parenthèses imbriquées, était refusée en permanence par la limite de cadence de GDELT (« larger queries »), après quatre paliers d''attente 20/40/60/90 s. La simplifiée répond 200 avec 50 articles, vérifié en réponse réelle le 23.08.2026.", "limite": 50, "fenetre": "7d", "requete": "(\\"medical device\\" OR \\"medical devices\\" OR medtech)", "requete_statut": "simplifiee_23.08.2026", "requete_anterieure": "(\\"medical device\\" (regulation OR investment OR manufacturing OR recall))"}'::jsonb, 'actif', 'N. Castillo', '2026-08-24'::date, 'GDELT DOC 2.0, requête SIMPLIFIÉE. Vue en réponse réelle le 23.08.2026, 50 articles. Réserve à porter au rapport : la requête précise, à parenthèses imbriquées, a été refusée durablement par le service (limitation de débit renvoyée en HTTP 200 avec corps non-JSON) ; la version simplifiée est un compromis dont la précision est moindre — les articles rendus ne sont pas tous pertinents.')
