INSERT INTO flux_sources (flux_id, famille, sector_code, libelle, url_base, parametres, statut, qualified_by, qualified_at, note)
VALUES ('boeing_communiques', 'communications', 'aerospatial', 'Boeing — communiqués de presse (fil RSS)', 'https://boeing.mediaroom.com/news-releases-statements?pagetemplate=rss', '{"_note": "Ajouté le 23.08.2026 — famille F2 du protocole OSINT, prévue en vague A par CONCEPTION_ETAGE2.md mais jamais implémentée : aucun descripteur ne la portait. Vérifié en réponse réelle le 23.08 (fil RSS valide, communiqués datés). AIRBUS ÉCARTÉ à la reconnaissance : son /rss.xml répond 200 mais ne sert que la navigation du site (« Environment », « Society »), pas les communiqués — un flux qui répond n''est pas pour autant un flux exploitable. Safran 403, Stryker 404, Medtronic sert du HTML, Swatch Group en délai d''attente, ACEA rend un fil vide."}'::jsonb, 'actif', 'N. Castillo', '2026-08-24'::date, 'Fil de syndication des communiqués Boeing. Vu en réponse réelle le 23.08.2026, 5 items. Source primaire de constructeur : ce qu''elle publie est daté et attribuable, ce qui la distingue des reprises de presse.')
